import{_ as e,o,c as a,a4 as r}from"./chunks/framework.9tZL7ZIQ.js";const b=JSON.parse('{"title":"1991年 · 超级帝国的责任","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1991年.md","filePath":"05_quotes/by-year/1991年.md"}'),l={name:"05_quotes/by-year/1991年.md"};function u(q,t,s,c,_,h){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="_1991年-·-超级帝国的责任" tabindex="-1">1991年 · 超级帝国的责任 <a class="header-anchor" href="#_1991年-·-超级帝国的责任" aria-label="Permalink to &quot;1991年 · 超级帝国的责任&quot;">​</a></h1><blockquote><p>&quot;我们不会拆分股份，拆分股份会增加交易成本，更容易让股价偏离内在价值，我们吸引不了更多短线交易者，我们想要长线投资者，我们现在股东群体就是对的，我们不想换。&quot;——巴菲特（61岁）</p></blockquote><p>本页收录1991年致股东信中的经典语录。巴菲特在这一年净资产突破70亿美元，讲述了喜诗糖果二十年里程碑带给他的投资领悟，并坦承了错过范妮梅的错误。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;真正重要的不是盈利记不记在我们账上，在乎这些盈利能不能帮我们增值。&quot;</p></blockquote><blockquote><p>&quot;什么是经济特许经营权：产品或服务，(1) 消费者需要或者想要；(2) 消费者觉得没有替代品；(3) 价格不受管制。有这三个，就能持续涨价，赚高ROE，哪怕管理层笨一点也不会死，坏管理只能削弱，不能杀死特许经营权。&quot;</p></blockquote><blockquote><p>&quot;反过来，你要靠低成本才能赚钱，这个优势持续不了多久，管理层笨一点就完了。&quot;</p></blockquote><blockquote><p>&quot;凯恩斯说过，&#39;真正正确的投资方法，就是把相当大资金放到你懂、管理层你信任的企业，不要分散。&#39;我就是这样，我们不可能找到很多好企业，为什么我们要买一堆我们不懂的，我们已经找到几个，足够了。&quot;</p></blockquote><blockquote><p>&quot;我们买了吉列这些好公司，我很开心，就算我退休也不会卖，我们就是喜欢拿着好公司，我们不折腾。&quot;</p></blockquote><blockquote><p>&quot;错过大机会比做错事亏大钱伤害更大，但是错过错了没办法，你能力圈外面，你没办法。&quot;</p></blockquote><blockquote><p>&quot;我们透视盈利，如果我们要达到平均每年15%增长，透视盈利必须每年增长15%。去年透视盈利下降了，主要是因为媒体盈利下降，还有吉列优先股转普通股减少报告收益3500万。&quot;</p></blockquote><blockquote><p>&quot;媒体行业特许经营权慢慢削弱了，因为零售模式变了，广告娱乐选择越来越多。以前预期盈利每年涨6%不用加资本就能做到，现在只能预期盈利围绕基准波动，这个变化太大了。&quot;</p></blockquote><blockquote><p>&quot;我们太幸运了，我们和喜欢欣赏的人做生意，为什么要换给不认识不喜欢的？已经很好了。&quot;</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1991年伯克希尔净值增长21亿美元，增幅39.6%，净资产突破74亿美元。可口可乐和吉列两家公司贡献了16亿美元增值，估值大幅提升。巴菲特首次买入健力士（英国洋酒公司），开始了首次大规模海外投资。H.H. Brown鞋业公司被收购，弗兰克·鲁尼继续担任CEO。范妮梅的错误被公开承认——1988年买了700万股后因涨了就停止加仓，错过了约14亿美元收益。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-1991年-翻译-·-01-letters-1991年-核心总结-·-01-letters-1991年-思维导图" tabindex="-1"><a href="/01_letters/1991年/翻译">01_letters/1991年/翻译</a> · <a href="/01_letters/1991年/核心总结">01_letters/1991年/核心总结</a> · <a href="/01_letters/1991年/思维导图">01_letters/1991年/思维导图</a> <a class="header-anchor" href="#_01-letters-1991年-翻译-·-01-letters-1991年-核心总结-·-01-letters-1991年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/1991年/翻译]] · [[→ 核心总结|01_letters/1991年/核心总结]] · [[→ 思维导图|01_letters/1991年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/1991年/翻译">/01_letters/1991年/翻译</a></li></ul>',22)])])}const n=e(l,[["render",u]]);export{b as __pageData,n as default};
